-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "近战 DPS"
L["rm.era.rogue.dps.Description"] = "1–60 级，所有专精，也适用于专家模式和自给自足服务器；综合 模拟器、Icy Veins 和 Wowhead。潜行时：预谋，持匕首且目标未面对你时使用伏击，单刷时偷袭，团队副本之外使用绞喉。战斗中：还击，精英或生命值充足的目标身上没有切割时从一个连击点起使用切割（在最后三秒内于五个连击点时续上），组队时若你有强化破甲 2/2 且没人使用破甲攻击，则在五个连击点时使用破甲，对即将死亡的目标使用两个连击点的刺骨，否则在五个连击点时使用刺骨，并且绝不攒超过五点。攒点技能取决于你已学会的技能：团队副本之外使用鬼魅攻击和出血，持匕首且目标未面对你时使用背刺，否则使用邪恶攻击。提醒：每把武器上的毒药（携带副手武器时副手使用致命毒药）、脚踢、菊花茶，在精英或两个敌人且切割生效时使用剑刃乱舞和冲动，五个连击点时使用冷血，单刷受伤时使用闪避。消失、凿击、伺机待发、肾击和种族技能列为关闭状态；佯攻、疾跑、致盲、闷棍和站位由你自己掌控。"
L["rm.era.rogue.dps.simulator.Name"] = "剑，挥击同步邪恶攻击（模拟器）"
L["rm.era.rogue.dps.simulator.Description"] = "模拟器 针对剑类武器专精的“极限”战斗顺序，是推荐的近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。邪恶攻击仅在主手挥击之后立即使用（距下次挥击 2.0 秒或以上，按 2.6–2.8 速度的剑设置；可在复制的循环中修改），除非能量接近满值或目标即将死亡，这样额外的剑类攻击不会推迟你的挥击。五个连击点的刺骨也会等待切割、满能量或濒死目标。其余与推荐的内置循环相同。"
L["rm.era.rogue.dps.warcrafttavern.Name"] = "近战 DPS，五连击点终结技（Warcraft Tavern）"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "Warcraft Tavern 的打法，是推荐的近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。每个终结技都等到五个连击点，让无情打击返还能量。切割从第二级（42 级）起在缺失或即将结束时使用，否则使用刺骨；不使用低连击点的切割，不对濒死目标使用刺骨，也不使用破甲（战士的破甲攻击会覆盖它）。潜行起手、攒点技能和提醒与推荐的内置循环相同。"
L["rm.forever.rogue.dps.Name"] = "近战 DPS"
L["rm.forever.rogue.dps.Description"] = "适用于所有潜行者专精 1 至 60 级的近战伤害，综合 Icy Veins、Wowhead 和 Warcraft Tavern。攒点技能取决于你已学会的技能：毁伤（第五个连击点用邪恶攻击）、出血、目标未面对你时使用背刺，否则使用邪恶攻击。潜行时以预谋起手，单刷时偷袭，组队面对精英时敏锐使用绞喉，否则使用伏击或绞喉。保持切割和毒针，组队对精英且没有战士叠满五层破甲攻击时使用破甲，然后把五个连击点用于割裂（敏锐，长时间战斗）或刺骨，且绝不攒超过五点。提醒：每把武器上的毒药、脚踢、对怪群和精英使用剑刃乱舞和冲动、冷血、闪避、佯攻、菊花茶和伺机待发。由你自己掌控：消失、疾跑、肾击、致盲、闷棍和站位。永久服限制了战斗数据，因此 Rotation Master 仅将此内置循环列出供参考，暂不会自动选择它。"
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "敏锐，伏击流（Warcraft Tavern）"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "Warcraft Tavern 的伏击/割喉敏锐流派：每次起手都用预谋和伏击，割喉允许时再次伏击，以背后背刺作为攒点技能（目标面对你时用出血），鬼魅攻击冷却完毕即用，切割，然后在五个连击点时使用刺骨，不使用割裂。会提醒你在首领被坦克拉住时消失以再次伏击。如果你点了割喉天赋，请选择它而非推荐的潜行者内置循环；它在以敏锐为主要天赋树且已点出割喉时适用。毒药和冷却技能提醒与推荐的内置循环相同。它是推荐的潜行者 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.forever.rogue.subtlety.wowhead.Name"] = "敏锐，绞喉流（Wowhead）"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "Wowhead 的敏锐：每次起手都用预谋和绞喉，并在循环中使用消失（随后伺机待发），在上一次绞喉结束后再次以绞喉起手。保持切割，组队时使用破甲，割裂作为五连击点终结技，出血是唯一的攒点技能。这会把你的逃生技能消失用于输出：请谨慎选择。它在以敏锐为主要天赋树、已点出卑鄙手段且已学会预谋时适用。毒药和冷却技能提醒与推荐的内置循环相同。它是推荐的潜行者 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.mop.rogue.assassination.Name"] = "推荐"
L["rm.mop.rogue.assassination.Description"] = "推荐奇袭专精使用，适用于 10 至 90 级（第 5 阶段依据 模拟器 和 Wowhead，升级步骤依据 Icy Veins）。潜行时单刷以偷袭开场，否则用毁伤（盲点触发时用斩击，需要匕首）。保持切割（60 级起由毒伤刷新）和目标身上的割裂，割裂持续期间在五个连击点使用毒伤，没有预感时在四个连击点使用毒伤以保持其增益效果滚动，然后是死亡标记，低于 35% 或盲点触发时使用斩击（主手需要匕首），以及毁伤。有四个或更多敌人与你交战时：切割、七个敌人时使用猩红风暴、割裂、毒伤和刀扇；切换目标把割裂施加到其他目标上由你决定。单刷时会加入复原，生命值低时加入肾击。提醒：毒药、脚踢、长时间战斗中使用仇杀、配合仇杀使用暗影之刃、仇杀期间使用消失和伺机待发、远处时使用暗影步、单刷时使用闪避。由你自己掌控：嫁祸诀窍和破甲（已列出但关闭）、佯攻、疾跑和站位。"
L["rm.mop.rogue.assassination.icyveins.Name"] = "五连击点毒伤（Icy Veins）"
L["rm.mop.rogue.assassination.icyveins.Description"] = "默认关闭。Icy Veins 和 Method 的顺序：消失冷却完毕即用，以便在潜行状态下使用毁伤，战斗时间足够长时仇杀冷却完毕即用，毒伤仅在五个连击点时使用，保持割裂，低于 35% 或盲点触发时使用斩击，毁伤。四到八个敌人：刀扇，三个连击点或以上时使用割裂；九个或更多：只用刀扇和毒伤。推荐的奇袭内置循环遵循较新的第 5 阶段建议；要使用这个，请启用它并禁用推荐的循环。"
L["rm.mop.rogue.combat.Name"] = "推荐"
L["rm.mop.rogue.combat.Description"] = "推荐战斗专精使用，适用于 10 至 90 级（第 5 阶段依据 Wowhead 和 模拟器）。自决战奥格瑞玛版本起，影袭消耗 50 点能量，因此以要害打击作为攒点技能，影袭仅在嗜血或英勇期间配合冲动使用（以及 20 级之前）。单刷时以偷袭开场，否则用伏击。从两个连击点起保持切割，并保持目标身上的要害打击，仅在要害打击生效时消耗五个连击点（切割、没有剑刃乱舞的长时间单体战斗中使用割裂、刺骨），五个连击点时等待能量。八个或更多敌人时：切割、猩红风暴和刀扇。单刷时会加入复原和肾击。提醒：毒药、脚踢、面对两个或更多敌人时开启剑刃乱舞并在之后关闭、能量低时配合暗影之刃使用冲动、杀戮盛筵、深度洞悉期间为伏击使用消失和伺机待发、暗影步、单刷时使用闪避。由你自己掌控：嫁祸诀窍和破甲（已列出但关闭）、佯攻以及为伏击站到目标背后。"
L["rm.mop.rogue.combat.hekili.Name"] = "预感（Hekili）"
L["rm.mop.rogue.combat.hekili.Description"] = "默认关闭。Hekili 针对带预感天赋的战斗专精的熊猫人之谜顺序：要害打击是唯一的攒点技能，嗜血期间也是如此；终结技会等待深度洞悉、四层预感充能或暗影之刃即将就绪，然后是切割、对一两个能存活较久的目标使用割裂、七个敌人时使用猩红风暴以及刺骨；盗匪之诈达到 11 层时提前刷新切割；四个敌人起使用刀扇。仅在点了预感天赋时适用。启用它并禁用推荐的战斗内置循环即可使用。"
L["rm.mop.rogue.combat.icyveins.Name"] = "影袭攒点（Icy Veins）"
L["rm.mop.rogue.combat.icyveins.Description"] = "默认关闭，在第 5 阶段已被取代。Icy Veins、Warcraft Tavern、Method 和 wowtbc.gg 在决战奥格瑞玛版本之前的顺序：切割，保持要害打击，长时间单体战斗中使用五连击点割裂以及刺骨，以影袭作为攒点技能。提醒和怪群打法与推荐的战斗内置循环相同。仅在你遵循这些指南时选择它；启用它并禁用推荐的循环。"
L["rm.mop.rogue.subtlety.Name"] = "推荐"
L["rm.mop.rogue.subtlety.Description"] = "推荐使用暗影集中的敏锐专精使用，适用于 10 至 90 级（第 5 阶段依据 模拟器 和 Wowhead）。潜行或暗影之舞期间：预谋、拉怪前的切割、五个连击点的终结技、伏击、锁喉。其他时候：切割；五个连击点时，切割和割裂即将消失就续上，两者都在时使用刺骨；死亡标记；用出血保持其流血效果；目标没有攻击你时使用背刺（持匕首时），否则使用出血。三个或更多敌人时：切割、猩红风暴、刺骨和刀扇。单刷时会加入复原和肾击。提醒：毒药、脚踢、75 点能量且切割和割裂都生效时使用暗影之舞、洞悉弱点即将结束时使用消失、伺机待发、暗影之舞和潜行之外使用暗影之刃、暗影步、单刷时使用闪避。由你自己掌控：站到目标背后（RM 无法看到朝向）、嫁祸诀窍和破甲（已列出但关闭）。"
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "诡诈（Warcraft Tavern）"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "当你的第一层天赋为诡诈时（Warcraft Tavern 的天赋构建），会代替暗影集中内置循环自动选择。拉怪前使用预谋和切割；潜行、暗影之舞或诡诈的延续期间，在五个连击点使用终结技，然后尽可能多地使用伏击。两到三个敌人：保持割裂，五个连击点用于猩红风暴而不是刺骨；四个或更多时加入刀扇。单个目标：切割、割裂、刺骨、用出血保持其流血效果、持匕首时在背后使用背刺，否则使用出血。暗影之舞和消失在 60 点能量且切割生效时作为提醒；按 Tavern 的建议配合饰品触发使用它们由你决定。"
L["rm.mop.rogue.unspecialized.Name"] = "无专精"
L["rm.mop.rogue.unspecialized.Description"] = "适用于 1 至 9 级，或尚未选择专精的潜行者；选择专精后由各专精的内置循环接管。潜行时单刷以偷袭开场，否则用伏击或影袭；脱战时建议潜行；从两个连击点起使用切割，单刷受伤时使用复原和肾击，四个连击点时使用刺骨（目标即将死亡时两个），影袭。提醒：学会后的毒药、脚踢、单刷时使用闪避。"
L["rm.retail.rogue.assassination.Name"] = "暴雪战斗辅助"
L["rm.retail.rogue.assassination.Description"] = "推荐至暗之夜的奇袭专精使用。在战斗中，游戏现在会对插件隐藏你的流血效果、增益效果、能量、冷却时间和生命值，因此它会显示暴雪自己的战斗辅助建议（一键循环，它会处理潜行起手、锁喉、割裂、毒伤、死亡印记和君王之灾），并在你施法或没有选中敌人时停止。提醒它未包含的内容：拉怪间隙的一种致命药膏、一种非致命药膏和潜行、战斗中不在潜行状态时使用消失、对可打断的施法使用脚踢（只在游戏允许读取该施法的场合亮起）。生命值在正式服中是隐藏的，因此猩红之瓶由你自己决定。"
L["rm.retail.rogue.assassination.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.rogue.assassination.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft 的施放顺序按计时维持流血效果，而至暗之夜会在战斗中隐藏这些信息；能量在正式服中是隐藏的，所以积攒能量被省略了。潜行中先使用锁喉，然后使用伏击。连击点数未满时在锁喉剩余最后 30% 时刷新锁喉，5 点以上连击点数时在割裂剩余最后 30% 时刷新割裂；5 点以上连击点数时使用致命一击或毒伤；不足 5 点时：三个或更多敌人使用猩红风暴，近处有两个或更多敌人时使用刀扇，伏击，毁伤。提醒：两种流血效果都生效时使用死亡印记、同时使用君王之灾、死亡印记就绪时使用消失、对带有死亡猎手标记的目标使用毒刃、战斗中蓟叶茶一就绪就使用，以及通用的毒药、潜行和脚踢提醒。"
L["rm.retail.rogue.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.rogue.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是潜行者的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有潜行者内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.retail.rogue.outlaw.Name"] = "暴雪战斗辅助"
L["rm.retail.rogue.outlaw.Description"] = "推荐至暗之夜的狂徒专精使用。显示暴雪的战斗辅助建议（它会处理潜行起手、命运骨骰、剑刃乱舞、冲动、正中眉心和终结技），并在你施法或没有选中敌人时停止。提醒它未包含的内容：拉怪间隙的毒药和潜行、战斗中不在潜行状态时使用消失、脚踢。生命值在正式服中是隐藏的，因此猩红之瓶由你自己决定。时运继延仍由你自己掌控：游戏会隐藏你拥有几个命运骨骰增益效果。"
L["rm.retail.rogue.outlaw.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins、SimulationCraft 和 Wowhead 的施放顺序需要读取命运骨骰增益效果、可乘之机层数和能量，而至暗之夜会在战斗中隐藏它们。潜行中使用伏击。连击点数距离满值只差一点或已满时：正中眉心，影舞步，致命一击，斩击。否则胆大妄为触发时使用伏击，可乘之机达到六层时使用手枪射击（连击点数低时三层即可），伏击，影袭。提醒：没有骰子增益时使用命运骨骰、连击点数不超过两点时使用冲动、两个或更多敌人时保持剑刃乱舞、刀锋冲刺、冲动、正中眉心和刀锋冲刺都在冷却时使用伺机待发。时运继延需要手动使用。"
L["rm.retail.rogue.subtlety.Name"] = "暴雪战斗辅助"
L["rm.retail.rogue.subtlety.Description"] = "推荐至暗之夜的敏锐专精使用。显示暴雪的战斗辅助建议（它会处理潜行起手、暗影之刃、赤喉之咬、暗影之舞、影分身和终结技），并在你施法或没有选中敌人时停止。提醒它未包含的内容：拉怪间隙的毒药和潜行、对可打断的施法使用脚踢。生命值在正式服中是隐藏的，因此猩红之瓶由你自己决定。"
L["rm.retail.rogue.subtlety.icyveins.Name"] = "参考（Icy Veins）"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "仅供参考，默认关闭：Icy Veins 和 SimulationCraft 的施放顺序会为影分身保留暗影之舞，并需要读取暗影之舞、至黑之夜和能量，而至暗之夜会在战斗中隐藏它们。拉怪前处于潜行状态：暗影打击。连击点数距离满值只差一点或已满时：有至黑之夜时使用刺骨，暗影之舞期间使用影分身，致命一击，三个或更多敌人时使用黑火药，刺骨。否则使用暗影打击，两个或更多敌人时使用袖剑风暴，幽暗之刃或背刺。提醒：暗影之舞期间使用赤喉之咬、暗影之舞就绪时使用暗影之刃、影分身就绪或暗影之刃生效时，在连击点数不超过两点（或达到六点以上）时使用暗影之舞、不在潜行状态且连击点数不超过两点时使用消失。"
L["rm.sod.rogue.dps.Name"] = "近战 DPS（探索赛季）"
L["rm.sod.rogue.dps.Description"] = "探索赛季，1–60 级，符文在你铭刻后即会使用；综合 模拟器 第 6 阶段、Icy Veins 和 Zockify 第 8 阶段。潜行时：暗影打击，组队时绞喉，持匕首的背刺流派使用伏击，单刷时偷袭。有三个或更多敌人与你交战时：先使用短枪射击、猩红风暴和刀扇。然后割喉触发时使用伏击（持匕首时），保持三层军刀猛刺，毒药达到四层时使用剧毒之刃，从两个连击点起使用切割（从四点起续上，铭刻了直取要害时除外），没人使用破甲攻击或保持解离毒药时负责破甲，铭刻了诛灭时使用流血效果（猩红风暴，否则割裂；有军刀猛刺时不用），五个连击点时使用毒伤（铭刻前为刺骨），以及按手套符文选择的攒点技能：毁伤、军刀猛刺、背刺（持匕首时），否则邪恶攻击。提醒：每把武器上的临时附魔、脚踢、菊花茶、剑刃乱舞、冲动、冷血和闪避，以及铭刻了敏锐大师时用来刷新它的消失和伺机待发。"
L["rm.sod.rogue.dps.icyveins.Name"] = "近战 DPS，割裂触发诛灭（探索赛季，Icy Veins）"
L["rm.sod.rogue.dps.icyveins.Description"] = "Icy Veins 的探索赛季顺序，是推荐的探索赛季近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。每个终结技都在五个连击点时使用，首先是缺失或即将结束时的切割，然后铭刻了诛灭时保持割裂，然后是毒伤；剧毒之刃仅在毒药达到五层时使用；三个敌人时使用短枪射击或刀扇。潜行起手、攒点技能和提醒与推荐的内置循环相同；解离毒药由你自己负责。"
L["rm.sod.rogue.dps.zockify.Name"] = "近战 DPS，精简毒伤（探索赛季，Zockify）"
L["rm.sod.rogue.dps.zockify.Description"] = "Zockify 精简的探索赛季列表，是推荐的探索赛季近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。不用流血效果，也不用破甲。毒药达到四层时使用剧毒之刃，缺失时使用切割（从两个连击点起，有军刀猛刺时从四点起），五个连击点时使用毒伤，然后是手套符文的攒点技能。消失和冷血的爆发由你自己掌控。"
L["rm.sod.rogue.tank.Name"] = "坦克（探索赛季）"
L["rm.sod.rogue.tank.Description"] = "探索赛季的坦克，铭刻了只是皮肉伤时选用；综合 模拟器 第 6 阶段、Icy Veins、Zockify 和 Warcraft Tavern。还击，左右开弓冷却完毕即用，从一个连击点起使用刃舞（从三点起续上），从三点起使用切割（从四点起续上），三个或更多敌人时使用刀扇、猩红风暴和短枪射击，刃舞生效期间使用短枪射击，两个增益效果都存在时在五个连击点使用刺骨，能量较低时使用剧毒之刃，然后是军刀猛刺、毁伤或邪恶攻击。提醒：组队时你的目标攻击其他人时使用挑逗、脚踢、生命值低于一半时使用闪避、剑刃乱舞、冲动、菊花茶和武器毒药（副手毒药仅在持有副手武器时使用）。暗影步和解离毒药由你自己掌控。"
L["rm.tbc.rogue.dps.simulator.Name"] = "近战 DPS（模拟器）"
L["rm.tbc.rogue.dps.simulator.Description"] = "1–70 级，所有专精。潜行时：预谋，然后单刷时偷袭、组队时锁喉，否则伏击（主手持匕首时）。战斗中：还击，两个连击点起使用切割（在最后两秒内续上），对即将死亡的目标使用刺骨，五个连击点时若割裂能持续足够久则使用割裂（剑刃乱舞顺劈期间除外），否则使用刺骨。目标没有攻击你时用毁伤或背刺（匕首）攒连击点，否则用出血或影袭。会提醒你缺少的毒药、脚踢、剑刃乱舞和冲动、冷血以及闪避。破甲、肾击、佯攻、消失和站位由你自己掌控。"
L["rm.tbc.rogue.dps.wowhead.Name"] = "近战 DPS（Wowhead）"
L["rm.tbc.rogue.dps.wowhead.Description"] = "1–70 级，所有专精，遵循 Wowhead。潜行起手、攒点技能和提醒与 模拟器 版本相同，但切割从一个连击点起就使用，每个五连击点终结技都是刺骨：不使用割裂。破甲、肾击、佯攻、消失和站位由你自己掌控。它是推荐的 模拟器 近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
